const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Depok location (city center coordinates)
  const depok = ee.Geometry.Point([106.8294, -6.4025]).buffer(10000); // 10km radius

  // 2. Get 1990 data (Landsat 5)
  let col1990 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(depok)
    .filterDate('1990-01-01', '1990-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1990 = col1990.size().getInfo();
  console.log(`1990 Images found: ${size1990}`);

  if (size1990 === 0) {
    console.log('No Landsat 5 data for 1990');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get 2019 data (Landsat 8)
  let col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(depok)
    .filterDate('2019-01-01', '2019-12-31')
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images found: ${size2019}`);

  if (size2019 === 0) {
    console.log('No Landsat 8 data for 2019');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Cloud masking function for Landsat Collection 2
  function maskL8sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    const opticalBands = image.select(['SR_B.']).multiply(0.0000275).add(-0.2);
    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    const opticalBands = image.select(['SR_B.']).multiply(0.0000275).add(-0.2);
    return image.addBands(opticalBands, null, true)
      .updateMask(qaMask)
      .updateMask(saturationMask);
  }

  // 5. Calculate NDVI for both periods
  function addNDVI_L5(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    return image.addBands(ndvi);
  }

  function addNDVI_L8(image) {
    const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const ndvi1990 = col1990.map(maskL5sr).map(addNDVI_L5).select('NDVI').median();
  const ndvi2019 = col2019.map(maskL8sr).map(addNDVI_L8).select('NDVI').median();

  // 6. Calculate statistics
  const stats1990 = ndvi1990.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: depok,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean1990 = stats1990['NDVI_mean'];
  const count1990 = stats1990['NDVI_count'];

  console.log(`1990: Mean NDVI = ${mean1990}, Valid pixels = ${count1990}`);

  if (count1990 === 0 || count1990 === null) {
    console.log('No valid pixels for 1990 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1990 === null || mean1990 === undefined || mean1990 < -1 || mean1990 > 1) {
    console.log('Invalid NDVI calculation for 1990');
    console.log('<answer>C3</answer>');
    return;
  }

  const stats2019 = ndvi2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: depok,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean2019 = stats2019['NDVI_mean'];
  const count2019 = stats2019['NDVI_count'];

  console.log(`2019: Mean NDVI = ${mean2019}, Valid pixels = ${count2019}`);

  if (count2019 === 0 || count2019 === null) {
    console.log('No valid pixels for 2019 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean2019 === null || mean2019 === undefined || mean2019 < -1 || mean2019 > 1) {
    console.log('Invalid NDVI calculation for 2019');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and determine answer
  console.log(`Vegetation change: ${((mean2019 - mean1990) / mean1990 * 100).toFixed(2)}%`);

  if (mean2019 < mean1990) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
